import { test, expect } from './fixtures';

test('popover trigger reveals card', async ({ page }) => {
  const trigger = page.locator('popover\\.trigger');
  const card = page.locator('card');

  await expect(trigger).toBeVisible();
  await trigger.click();
  await expect(card).toBeVisible();
});

import { test, expect } from './fixtures';

test('renders user-entered diagram', async ({ page }) => {
  await page.goto('/#/');
  const editor = page.getByRole('textbox');
  await expect(editor).toBeVisible();
  await editor.fill('graph TD;\n  TestNode123 --> TestNode456;');
  await expect(page.locator('svg text', { hasText: 'TestNode123' })).toBeVisible();
  await expect(page.locator('svg text', { hasText: 'TestNode456' })).toBeVisible();
});
